<div class="gamification-admin-head"><h2><?php echo $this->lang('Tournaments') ?></h2><?php echo $this->button_create('admin/tournaments/add', (string)$this->lang('Create tournament')) ?></div><div class="table-responsive"><table class="table"><thead><tr><th><?php echo $this->lang('Tournament') ?></th><th><?php echo $this->lang('Dates') ?></th><th><?php echo $this->lang('Participants') ?></th><th><?php echo $this->lang('Status') ?></th><th><?php echo $this->lang('Actions') ?></th></tr></thead><tbody><?php foreach ($tournaments as $row): ?><tr><td><a href="<?php echo url('admin/tournaments/edit/'.$row['tournament_id']) ?>"><?php echo utf8_htmlentities($row['title']) ?></a><small><?php echo utf8_htmlentities($row['format']) ?></small></td><td><?php echo utf8_htmlentities($row['starts_at'] ?? '') ?></td><td><?php echo (int)$row['participant_count'] ?></td><td><?php echo utf8_htmlentities($row['status']) ?></td><td><a class="btn btn-secondary" href="<?php echo url('admin/tournaments/participants/'.$row['tournament_id']) ?>"><?php echo icon('fas fa-users') ?> <?php echo $this->lang('Participants') ?></a><?php echo $this->button_update('admin/tournaments/edit/'.$row['tournament_id']) ?><?php echo $this->button_delete('admin/tournaments/delete/'.$row['tournament_id']) ?></td></tr><?php endforeach ?></tbody></table></div>
